const urDigits = (n) => String(n).replace(/[0-9]/g, (d) => String.fromCharCode(0x06F0 + Number(d)));
const cp = (s) => Array.from(String(s == null ? '' : s));
const clip = (s, max) => {
  const c = cp(s);
  if (c.length <= max) return c.join('');
  const head = c.slice(0, max - 1).join('');
  const cut = head.lastIndexOf(' ');
  return `${(cut > max / 2 ? head.slice(0, cut) : head).trimEnd()}…`;
};
const langOf = FicoS.langOf;

