// The band's label → the level whose name it shares (Exemplary 4 … Below standard 1), for the Urdu score line.
function bandLevel(label) {
  const hit = Object.entries(FicoS.LEVEL_LABELS).find(([, v]) => v === label);
  return hit ? Number(hit[0]) : null;
}

const strings = (lang) => STR[langOf(lang)];
const atom = (lang, s) => strings(lang).atom(s);

// ── the screens ───────────────────────────────────────────────────────────────

const NUMBER_WORDS = ['ONE', 'TWO', 'THREE', 'FOUR', 'FIVE', 'SIX', 'SEVEN', 'EIGHT', 'NINE', 'TEN'];
const indicatorScreenId = (code) => {
  const sec = FicoS.indicator(code).section;
  const i = FicoS.sectionOf(sec).codes.indexOf(code);
  return `FS_${sec}_${NUMBER_WORDS[i]}`;
};
const levelField = (code) => `lv_${code}`;
const evidenceField = (code) => `ev_${code}`;
const changeField = (code) => `chg_${code}`;

// Field: { name (on the Flow), key (in the draft), input, required, check } — check: 'level' | 'evidence' | 'choice' |
// 'text' | 'yes_no'.
const SCREENS = [];
SCREENS.push({ id: 'FS_START', kind: 'start', fields: [] });
for (const sec of FicoS.SECTIONS) {
  SCREENS.push({ id: `FS_INTRO_${sec.key}`, kind: 'intro', section: sec.key, fields: [] });
  for (const code of sec.codes) {
    SCREENS.push({
      id: indicatorScreenId(code),
      kind: 'indicator',
      section: sec.key,
      code,
      fields: [
        { name: levelField(code), key: code, input: 'radio', required: true, check: 'level', code },
        { name: evidenceField(code), key: evidenceField(code), input: 'textarea', required: true, check: 'evidence', max: TEXTAREA_MAX },
        // Queue #184: why the observer changed Rumi's level (a Digital Coach visit only; required then, as v6's).
        ...(FicoS.isStarred(code) ? [] : [{ name: changeField(code), key: changeField(code), input: 'textarea', required: false, check: 'change', code, max: TEXTAREA_MAX }]),
      ],
    });
  }
}
SCREENS.push({
  id: 'FS_CHECKLIST',
  kind: 'checklist',
  // Required (operator 19 Nov): the observer stays here until each check is answered; Submit refuses too.
  fields: FicoS.RUBRIC.checklist.map((c) => ({ name: c.key, key: c.key, input: 'radio', required: true, check: 'yes_no' })),
});
SCREENS.push({
  id: 'FS_FEEDBACK',
  kind: 'feedback',
  fields: [
    { name: 'fb_strengths', key: 'fb_strengths', input: 'textarea', required: true, check: 'text', max: TEXTAREA_MAX },
    { name: 'fs_focus', key: 'fs_focus', input: 'dropdown', required: true, check: 'choice' },
    { name: 'fs_action', key: 'fs_action', input: 'textarea', required: true, check: 'text', max: TEXTAREA_MAX },
    { name: 'fs_by', key: 'fs_by', input: 'textinput', required: false, check: 'text', max: TEXTINPUT_MAX },
    { name: 'fs_focus_2', key: 'fs_focus_2', input: 'dropdown', required: false, check: 'choice' },
    { name: 'fs_action_2', key: 'fs_action_2', input: 'textarea', required: false, check: 'text', max: TEXTAREA_MAX },
  ],
});
const BY_ID = Object.fromEntries(SCREENS.map((s) => [s.id, s]));
const PATH = SCREENS.map((s) => s.id);
const FIRST_SCREEN = PATH[0];

const pathFor = () => PATH.slice();
const screenById = (id) => BY_ID[id] || null;
const fieldsOf = (id) => (BY_ID[id] ? BY_ID[id].fields : []);
function nextOf(id) {
  const i = PATH.indexOf(id);
  return i >= 0 && i < PATH.length - 1 ? PATH[i + 1] : null;
}
const isSubmitScreen = (id) => id === PATH[PATH.length - 1];

// ── options ───────────────────────────────────────────────────────────────────

/** The level choices for one indicator: "3 · Proficient" with the sheet's words; then N/A in its own words where the version has one. */
function levelOptions(code, lang = 'en', rubric = FicoS.RUBRIC_KEY) {
  const t = FicoS.indicatorText(code, lang, rubric);
  const out = t.levels.map((text, i) => ({
    id: String(i + 1),
    title: clip(`${strings(lang).n(i + 1)} · ${FicoS.levelName(i + 1, lang)}`, 30),
    description: clip(text, 300),
  }));
  const na = FicoS.naOption(code, lang, rubric);
  if (na) out.push(na);
  return out;
}

/**
 * An indicator's text under its name: what to look for, then (v1.2) its scoring note, and the note that says why N/A
 * arrived chosen (C3 after C1 = 1). In the Flow's look_for and the portal's field text: no new slot, no republish.
 */
function lookForText(code, lang, rubric, { followed = false, withLookFor = true } = {}) {
  const t = FicoS.indicatorText(code, lang, rubric);
  const paras = [withLookFor ? t.look_for : ''];
  if (t.note) paras.push(t.note);
  if (followed) {
    const note = FicoS.naFollowNote(code, lang, rubric);
    if (note) paras.push(String(note).replace(/\b([A-E]\d)\b/g, (m) => atom(lang, m)));
  }
  return paras.filter(Boolean).join('\n\n');
}

/** Does this indicator's N/A arrive chosen (C3 when the observer set C1 to level 1 and has not chosen C3)? */
function followsNa(code, draft, rubric) {
  const f = FicoS.naFollows(code, rubric);
  if (!f) return false;
  const d = draft || {};
  if (has(d[code])) return false;
  return String(d[f.code]) === String(f.level);
}

/** The indicator list for the feedback's dropdowns: "C4 · Student voice & choice" (≤ 30), the full name below. */
function focusOptions(lang = 'en') {
  return FicoS.CODES.map((c) => {
    const name = FicoS.indicatorText(c, lang).name;
    return { id: c, title: clip(`${c} · ${name}`, 30), description: clip(name, 300) };
  });
}

const yesNo = (lang) => [{ id: 'yes', title: strings(lang).yes }, { id: 'no', title: strings(lang).no }];

// ── the check (pure) ──────────────────────────────────────────────────────────

const has = (v) => v !== undefined && v !== null && String(v).trim() !== '';

/**
 * The saved draft with one screen's posted values on top (keys as the draft keeps them). A field the Flow did not post
 * keeps what was saved; one posted blank was cleared by the observer.
 */
function mergeDraft(saved, screenId, posted = {}) {
  const out = { ...(saved || {}) };
  for (const f of fieldsOf(screenId)) {
    if (!Object.prototype.hasOwnProperty.call(posted, f.name)) continue;
    const v = posted[f.name] == null ? '' : String(posted[f.name]).trim();
    if (v === '') { delete out[f.key]; continue; }
    out[f.key] = f.max ? cp(v).slice(0, f.max).join('') : v;
  }
  return out;
}

/**
 * One screen's problems, { flowFieldName: code }, from the merged draft. `dc` (queue #184): Rumi's pre-fill kept on the
 * form row (obs612/fico-s-dc.js dcOf); a level changed from Rumi's then needs a reason of 20+ characters.
 */
function checkScreen(screenId, draft = {}, { dc = null, rubric = FicoS.RUBRIC_KEY } = {}) {
  const errors = {};
  const d = draft || {};
  for (const f of fieldsOf(screenId)) {
    const v = d[f.key];
    if (f.check === 'change') {
      if (dc && !require('./fico-s-dc').changeExplained(dc, f.code, d, rubric)) errors[f.name] = 'change';
    } else if (f.check === 'level') {
      if (FicoS.normLevel(v, f.code, rubric) === null) errors[f.name] = 'item';
    } else if (f.check === 'evidence') {
      if (!FicoS.isEvidence(v)) errors[f.name] = 'evidence';
    } else if (f.check === 'yes_no') {
      if (!has(v)) { if (f.required) errors[f.name] = 'yes_no'; } else if (!['yes', 'no'].includes(String(v))) errors[f.name] = 'choice';
    } else if (f.check === 'choice') {
      if (!has(v)) { if (f.required) errors[f.name] = 'choice'; } else if (!FicoS.CODES.includes(String(v))) errors[f.name] = 'choice';
    } else if (!has(v) && f.required) {
      errors[f.name] = 'text';
    }
  }
  if (screenId === 'FS_FEEDBACK') {
    if (has(d.fs_focus_2) || has(d.fs_action_2)) {
      if (!has(d.fs_focus_2) && !errors.fs_focus_2) errors.fs_focus_2 = 'row_two';
      if (!has(d.fs_action_2) && !errors.fs_action_2) errors.fs_action_2 = 'row_two';
    }
    if (has(d.fs_focus_2) && d.fs_focus_2 === d.fs_focus && !errors.fs_focus_2) errors.fs_focus_2 = 'same_focus';
  }
  return errors;
}

/** What is still needed before Submit: the draft keys of every unanswered required field, in form order. */
function whatIsMissing(draft = {}, { dc = null, rubric = FicoS.RUBRIC_KEY } = {}) {
  const missing = [];
  for (const s of SCREENS) {
    const errs = checkScreen(s.id, draft, { dc, rubric });
    for (const f of s.fields) if (errs[f.name] && (f.required || f.check === 'change')) missing.push(f.key);
  }
  return missing;
}

/** Where a missing answer is, in the observer's words: 'A1 Lesson objective (SLO)' or the feedback field's label. */
function whereIs(key, lang = 'en') {
  const code = key.startsWith('ev_') ? key.slice(3) : key.startsWith('chg_') ? key.slice(4) : key;
  if (FicoS.CODES.includes(code)) return `${atom(lang, code)} ${FicoS.indicatorText(code, lang).name}`;
  const s = strings(lang);
  const check = FicoS.RUBRIC.checklist.findIndex((c) => c.key === key);
  if (check >= 0) return s.cl_where(check + 1);
  const label = { fb_strengths: s.lbl_strengths, fs_focus: s.lbl_focus, fs_action: s.lbl_action }[key];
  return label || key;
}

function missingNote(missing, lang = 'en') {
  const seen = [];
  for (const k of missing) {
    const w = whereIs(k, lang);
    if (!seen.includes(w)) seen.push(w);
  }
  const shown = seen.slice(0, 3);
  return strings(lang).missing(shown.join(strings(lang).list_sep), seen.length - shown.length);
}

// ── each screen's data ────────────────────────────────────────────────────────

function errorData(screen, lang, { errors = {}, note = '' } = {}) {
  const s = strings(lang);
  const messages = Object.fromEntries(Object.entries(errors).map(([k, code]) => [k, s.err[code] || code]));
  return { err_v: Boolean(note), err_note: note || '', error_messages: messages };
}

function prefill(f, draft, rubric = FicoS.RUBRIC_KEY) {
  const v = draft[f.key];
  if (!has(v)) return '';
  if (f.check === 'level') return FicoS.normLevel(v, f.code, rubric) === null ? '' : String(v);
  return String(v);
}

/** Queue #184: what an indicator screen says of Rumi's pre-fill ({ show, line }); nothing on a visit Rumi did not fill. */
function rumiData(code, lang, dc, rubric = FicoS.RUBRIC_KEY) {
  if (!dc || !dc.levels || FicoS.isStarred(code)) return { show: false, line: '' };
  const s = strings(lang);
  const row = dc.levels[code];
  const lv = require('./fico-s-dc').rumiLevelOf(dc, code, rubric);
  if (lv === 'NA') return { show: true, line: s.rumi_chose(FicoS.naTitle(code, lang, rubric) || s.na_title) };
  if (lv !== null) return { show: true, line: s.rumi_chose(`${s.n(Number(lv))} · ${FicoS.levelName(Number(lv), lang)}`) };
  const why = row && String(row.because || '').trim();
  return { show: true, line: why ? s.rumi_none_why(clip(why, 160)) : s.rumi_none };
}

/**
 * A screen's data in the observer's language. `draft` pre-fills what was saved; `opts.errors` ({flowField: code}) and
 * `opts.note` show the check's result.
 */
function screenData(screenId, draft = {}, lang = 'en', opts = {}) {
  const screen = BY_ID[screenId];
  if (!screen) return {};
  const s = strings(lang);
  const d = draft || {};
  const rubric = FicoS.isFicoSId(opts.rubric) ? opts.rubric : FicoS.RUBRIC_KEY;
  const label = FicoS.labelOf(rubric);
  if (screen.kind === 'start') {
    return { rubric_label: label, heading: s.start_heading, body: s.start_body, next_label: s.start_next };
  }
  if (screen.kind === 'intro') {
    const sec = FicoS.sectionOf(screen.section);
    return {
      rubric_label: label,
      heading: clip(`${s.section(sec.key)} · ${FicoS.sectionName(sec.key, lang)}`, 80),
      question: FicoS.sectionQuestion(sec.key, lang),
      count_line: s.intro_count(sec.codes.length),
      list: sec.codes.map((c) => `${atom(lang, c)}  ${FicoS.indicatorText(c, lang).name}`).join('\n'),
      next_label: clip(s.intro_next(sec.key), 35),
    };
  }
  if (screen.kind === 'indicator') {
    const code = screen.code;
    const t = FicoS.indicatorText(code, lang);
    const sec = FicoS.sectionOf(screen.section);
    const init = {};
    for (const f of screen.fields) init[f.name] = prefill(f, d, rubric);
    // v1.2: C3 arrives on N/A when the observer set C1 to level 1 (and the screen says why); their own choice wins.
    const followed = followsNa(code, d, rubric);
    if (followed) init[levelField(code)] = 'NA';
    // The star marks what Rumi does not score, so it shows on a Digital Coach visit only: a visit Rumi did not fill
    // looks exactly as before (and Flow v1 and v2 render it the same).
    const starred = FicoS.isStarred(code) && Boolean(opts.dc && opts.dc.levels);
    const rumi = rumiData(code, lang, opts.dc, rubric);
    return {
      rubric_label: label,
      progress: s.progress(sec.key, sec.codes.indexOf(code) + 1, sec.codes.length),
      heading: clip(`${starred ? '★ ' : ''}${atom(lang, code)} · ${t.name}`, 80),
      star_v: starred,
      star_line: starred ? s.star_line : '',
      rumi_v: rumi.show,
      rumi_line: rumi.line,
      chg_v: rumi.show && !starred,
      lbl_chg: s.lbl_chg,
      help_chg: s.help_chg,
      look_for: lookForText(code, lang, rubric, { followed }),
      how_line: s.how(t.how),
      back_hint: s.back_hint,
      lbl_level: s.lbl_level,
      opts: levelOptions(code, lang, rubric),
      lbl_ev: s.lbl_ev,
      help_ev: s.help_ev,
      next_label: s.next,
      init,
      ...errorData(screen, lang, opts),
    };
  }
  if (screen.kind === 'checklist') {
    const data = { rubric_label: label, heading: s.cl_heading, note: s.cl_note, back_hint: s.back_hint, next_label: s.next, yes_no: yesNo(lang) };
    const init = {};
    FicoS.RUBRIC.checklist.forEach((c, i) => {
      data[`${c.key}_lbl`] = clip(`${s.n(i + 1)}. ${s.group(c.group)}`, 30);
      data[`${c.key}_text`] = clip(FicoS.checklistText(c.key, lang), 300);
      init[c.key] = ['yes', 'no'].includes(d[c.key]) ? d[c.key] : '';
    });
    return { ...data, init, ...errorData(screen, lang, opts) };
  }
  // feedback
  const r = FicoS.score(Object.fromEntries(FicoS.CODES.map((c) => [c, d[c]])), rubric);
  const lines = [s.score_line(r), ...r.sections.map((x) => s.section_line(x))];
  if (r.na.length) lines.push(s.na_line(r.na));
  const lowest = FicoS.lowestIndicator(d, rubric);
  const init = {
    fb_strengths: has(d.fb_strengths) ? String(d.fb_strengths) : '',
    fs_focus: FicoS.CODES.includes(d.fs_focus) ? d.fs_focus : (lowest ? lowest.code : ''),
    fs_action: has(d.fs_action) ? String(d.fs_action) : '',
    fs_by: has(d.fs_by) ? String(d.fs_by) : '',
    fs_focus_2: FicoS.CODES.includes(d.fs_focus_2) ? d.fs_focus_2 : '',
    fs_action_2: has(d.fs_action_2) ? String(d.fs_action_2) : '',
  };
  return {
    rubric_label: label,
    heading: s.fb_heading,
    score_lines: r.max ? lines.join('\n') : '',
    rule: s.fb_rule,
    back_hint: s.back_hint,
    lbl_strengths: s.lbl_strengths,
    help_strengths: s.help_strengths,
    lbl_focus: s.lbl_focus,
    focus_opts: focusOptions(lang),
    lbl_action: s.lbl_action,
    help_action: s.help_action,
    lbl_by: s.lbl_by,
    help_by: s.help_by,
    focus_two: s.focus_two,
    lbl_focus_2: s.lbl_focus_2,
    lbl_action_2: s.lbl_action_2,
    next_label: s.submit,
    init,
    ...errorData(screen, lang, opts),
  };
}

function noticeData(refusal, lang = 'en', rubric = FicoS.RUBRIC_KEY) {
  const s = strings(lang);
  const [title, body] = s.refused[refusal] || s.refused.error;
  return { rubric_label: FicoS.labelOf(rubric) || FicoS.LABEL, notice_title: title, notice_body: body, close_label: s.close_label };
}

function doneData(outcome, formId, lang = 'en', lines = null, rubric = FicoS.RUBRIC_KEY) {
  const s = strings(lang);
  const [title, body] = lines || s.done[outcome] || s.refused[outcome] || s.done.error;
  return { rubric_label: FicoS.labelOf(rubric) || FicoS.LABEL, done_title: title, done_body: body, outcome, form_id: String(formId || ''), done_label: s.done_label };
}

// ── the portal's door (obs612/portal.js) ──────────────────────────────────────
// The portal fills the same form: the same fields (named by their draft key there), the same check, the same record.

/** Every field, named by its draft key, with what the portal's merge and clean need. */
function portalFields(lang = 'en', { rubric = FicoS.RUBRIC_KEY } = {}) {
  return SCREENS.flatMap((s) => s.fields.map((f) => {
    let options = null;
    if (f.check === 'level') options = levelOptions(f.code, lang, rubric);
    else if (f.check === 'yes_no') options = yesNo(lang);
    else if (f.check === 'choice') options = focusOptions(lang);
    return { name: f.key, input: f.input, required: f.required, prefill: true, max: f.max || null, options, check: f.check, code: f.code || null };
  }));
}

/** Every screen's check on the draft, keyed by draft key: { A1: 'item', ev_A1: 'evidence', fs_focus: 'choice' … }. */
function errorsByKey(draft = {}, { dc = null, rubric = FicoS.RUBRIC_KEY } = {}) {
  const out = {};
  for (const s of SCREENS) {
    const errs = checkScreen(s.id, draft, { dc, rubric });
    for (const f of s.fields) if (errs[f.name]) out[f.key] = errs[f.name];
  }
  return out;
}

/**
 * The form as the portal shows it (obs612/portal.js part shapes): one section a screen, in the Flow's order, every
 * word in the observer's language. An indicator is an 'item' field (its chip: "A1 · Lesson objective (SLO)", its text:
 * what to look for and how; the four levels one under another), then its evidence box.
 */
function portalSections(draft = {}, lang = 'en', { dc = null, rubric = FicoS.RUBRIC_KEY } = {}) {
  const s = strings(lang);
  const fieldsByKey = Object.fromEntries(portalFields(lang, { rubric }).map((f) => [f.name, f]));
  const field = (key, role, text, extra = {}) => {
    const f = fieldsByKey[key];
    return {
      type: 'field', name: key, role, input: f.input, kind: extra.kind || null, n: null, short: extra.short || null,
      text, options: f.options, required: f.required, max: f.max,
      ...(extra.follows ? { follows: extra.follows } : {}),
      // bd-o15qnr.37: an indicator's line on what it looks at (#217's guide line) and its text without the look-for
      // paragraph, so the portal shows the line under the name and does not say it twice; `text` is unchanged.
      ...(extra.about !== undefined ? { about: extra.about, notes: extra.notes } : {}),
    };
  };
  return SCREENS.map((screen) => {
    const parts = [];
    if (screen.kind === 'start') {
      parts.push({ type: 'heading', text: s.start_heading });
      for (const para of s.start_body.split('\n\n')) parts.push({ type: 'sub', text: para });
    } else if (screen.kind === 'intro') {
      parts.push({ type: 'heading', text: `${s.section(screen.section)} · ${FicoS.sectionName(screen.section, lang)}` });
      parts.push({ type: 'sub', text: FicoS.sectionQuestion(screen.section, lang) });
    } else if (screen.kind === 'indicator') {
      const code = screen.code;
      const t = FicoS.indicatorText(code, lang);
      const sec = FicoS.sectionOf(screen.section);
      const starred = FicoS.isStarred(code) && Boolean(dc && dc.levels); // on a Digital Coach visit only
      const rumi = rumiData(code, lang, dc, rubric);
      parts.push({ type: 'heading', text: `${starred ? '★ ' : ''}${atom(lang, code)} · ${t.name}` });
      // Queue #184: the starred line, and Rumi's line and the change box on a Digital Coach visit.
      if (starred) parts.push({ type: 'sub', text: s.star_line });
      if (rumi.show) parts.push({ type: 'sub', text: rumi.line });
      const follows = FicoS.naFollows(code, rubric);
      const followed = followsNa(code, draft, rubric);
      const rest = lookForText(code, lang, rubric, { followed, withLookFor: false });
      parts.push(field(code, 'item', `${lookForText(code, lang, rubric, { followed })}\n${s.how(t.how)}`, {
        kind: 'level', short: s.progress(sec.key, sec.codes.indexOf(code) + 1, sec.codes.length),
        about: Lines.lineFor(rubric, code, lang),
        notes: rest ? `${rest}\n${s.how(t.how)}` : s.how(t.how),
        // Queue #218: the portal pre-picks N/A as the observer sets C1 (Obs612Form.tsx); the Flow does it per screen.
        ...(follows ? { follows: { code: follows.code, level: String(follows.level) } } : {}),
      }));
      parts.push(field(evidenceField(code), 'other', `${s.lbl_ev}: ${s.help_ev}`));
      if (rumi.show && !starred) parts.push(field(changeField(code), 'other', `${s.lbl_chg}: ${s.help_chg}`));
    } else if (screen.kind === 'checklist') {
      parts.push({ type: 'heading', text: s.cl_heading });
      parts.push({ type: 'sub', text: s.cl_note });
      FicoS.RUBRIC.checklist.forEach((c, i) => {
        parts.push(field(c.key, 'item', FicoS.checklistText(c.key, lang), { kind: 'yes_no', short: `${s.n(i + 1)}. ${s.group(c.group)}` }));
      });
    } else {
      const r = FicoS.score(Object.fromEntries(FicoS.CODES.map((c) => [c, (draft || {})[c]])), rubric);
      parts.push({ type: 'heading', text: s.fb_heading });
      if (r.max) parts.push({ type: 'score', total: r.total, max: r.max, pct: r.pct, band: r.band ? r.band.label : null });
      parts.push({ type: 'sub', text: s.fb_rule });
      parts.push(field('fb_strengths', 'other', `${s.lbl_strengths}: ${s.help_strengths}`));
      parts.push(field('fs_focus', 'other', s.lbl_focus));
      parts.push(field('fs_action', 'other', `${s.lbl_action}: ${s.help_action}`));
      parts.push(field('fs_by', 'other', `${s.lbl_by}: ${s.help_by}`));
      parts.push({ type: 'sub', text: s.focus_two });
      parts.push(field('fs_focus_2', 'other', s.lbl_focus_2));
      parts.push(field('fs_action_2', 'other', s.lbl_action_2));
    }
    return { id: screen.id, parts };
  });
}

// ── Flow JSON ─────────────────────────────────────────────────────────────────

const str = (example) => ({ type: 'string', __example__: example });
const bool = (example) => ({ type: 'boolean', __example__: example });
const obj = (example) => ({ type: 'object', __example__: example });
const optionsDecl = (example) => ({
  type: 'array',
  items: { type: 'object', properties: { id: { type: 'string' }, title: { type: 'string' }, description: { type: 'string' } } },
  __example__: example,
});
const CAPTION = { type: 'TextCaption', text: '${data.rubric_label}' };

/** A screen's data declaration: every key screenData gives, typed, with an English example. */
function declare(example) {
  const out = {};
  for (const [k, v] of Object.entries(example)) {
    if (Array.isArray(v)) out[k] = optionsDecl(v);
    else if (typeof v === 'boolean') out[k] = bool(v);
    else if (v && typeof v === 'object') out[k] = obj(v);
    else out[k] = str(v == null ? '' : String(v));
  }
  return out;
}

function footer(screen, payload) {
  return { type: 'Footer', label: '${data.next_label}', 'on-click-action': { name: 'data_exchange', payload: { screen: screen.id, ...payload } } };
}

function screenJson(screen) {
  const ex = screenData(screen.id, {}, 'en');
  const data = declare(ex);
  let children;
  if (screen.kind === 'start') {
    children = [CAPTION, { type: 'TextHeading', text: '${data.heading}' }, { type: 'TextBody', text: '${data.body}' }, footer(screen, {})];
    return { id: screen.id, title: TITLE, data, layout: { type: 'SingleColumnLayout', children } };
  }
  if (screen.kind === 'intro') {
    children = [
      CAPTION,
      { type: 'TextHeading', text: '${data.heading}' },
      { type: 'TextBody', text: '${data.question}' },
      { type: 'TextCaption', text: '${data.count_line}' },
      { type: 'TextBody', text: '${data.list}' },
      footer(screen, {}),
    ];
    return { id: screen.id, title: TITLE, data, layout: { type: 'SingleColumnLayout', children } };
  }
  const payload = Object.fromEntries(screen.fields.map((f) => [f.name, `\${form.${f.name}}`]));
  const formChildren = [CAPTION];
  if (screen.kind === 'indicator') {
    const [lv, ev, chg] = screen.fields;
    // Queue #184: the starred line (a starred indicator only) and Rumi's line and the change box (a Digital Coach
    // visit only) are shown from the screen's data, so one published Flow serves every visit.
    formChildren.push(
      { type: 'TextCaption', text: '${data.progress}' },
      { type: 'TextHeading', text: '${data.heading}' },
      ...(FicoS.isStarred(screen.code) ? [{ type: 'TextBody', text: '${data.star_line}', visible: '${data.star_v}' }] : []),
      { type: 'TextBody', text: '${data.look_for}' },
      { type: 'TextCaption', text: '${data.how_line}' },
      { type: 'TextBody', text: '${data.err_note}', visible: '${data.err_v}' },
      ...(chg ? [{ type: 'TextBody', text: '${data.rumi_line}', visible: '${data.rumi_v}' }] : []),
      { type: 'RadioButtonsGroup', name: lv.name, label: '${data.lbl_level}', required: true, 'data-source': '${data.opts}' },
      { type: 'TextArea', name: ev.name, label: '${data.lbl_ev}', required: true, 'max-length': TEXTAREA_MAX, 'helper-text': '${data.help_ev}' },
      ...(chg ? [{ type: 'TextArea', name: chg.name, label: '${data.lbl_chg}', required: false, 'max-length': TEXTAREA_MAX, 'helper-text': '${data.help_chg}', visible: '${data.chg_v}' }] : []),
      { type: 'TextCaption', text: '${data.back_hint}' },
    );
  } else if (screen.kind === 'checklist') {
    formChildren.push(
      { type: 'TextHeading', text: '${data.heading}' },
      { type: 'TextBody', text: '${data.note}' },
      { type: 'TextBody', text: '${data.err_note}', visible: '${data.err_v}' },
      ...screen.fields.map((f) => ({
        type: 'RadioButtonsGroup', name: f.name, label: `\${data.${f.name}_lbl}`, description: `\${data.${f.name}_text}`, required: f.required, 'data-source': '${data.yes_no}',
      })),
      { type: 'TextCaption', text: '${data.back_hint}' },
    );
  } else {
    formChildren.push(
      { type: 'TextHeading', text: '${data.heading}' },
      { type: 'TextBody', text: '${data.score_lines}' },
      { type: 'TextBody', text: '${data.rule}' },
      { type: 'TextBody', text: '${data.err_note}', visible: '${data.err_v}' },
      { type: 'TextArea', name: 'fb_strengths', label: '${data.lbl_strengths}', required: true, 'max-length': TEXTAREA_MAX, 'helper-text': '${data.help_strengths}' },
      { type: 'Dropdown', name: 'fs_focus', label: '${data.lbl_focus}', required: true, 'data-source': '${data.focus_opts}' },
      { type: 'TextArea', name: 'fs_action', label: '${data.lbl_action}', required: true, 'max-length': TEXTAREA_MAX, 'helper-text': '${data.help_action}' },
      { type: 'TextInput', name: 'fs_by', label: '${data.lbl_by}', 'input-type': 'text', required: false, 'helper-text': '${data.help_by}' },
      { type: 'TextSubheading', text: '${data.focus_two}' },
      { type: 'Dropdown', name: 'fs_focus_2', label: '${data.lbl_focus_2}', required: false, 'data-source': '${data.focus_opts}' },
      { type: 'TextArea', name: 'fs_action_2', label: '${data.lbl_action_2}', required: false, 'max-length': TEXTAREA_MAX },
      { type: 'TextCaption', text: '${data.back_hint}' },
    );
  }
  formChildren.push(footer(screen, payload));
  return {
    id: screen.id,
    title: TITLE,
    data,
    layout: {
      type: 'SingleColumnLayout',
      children: [{
        type: 'Form',
        name: `${screen.id.toLowerCase()}_form`,
        'init-values': '${data.init}',
        'error-messages': '${data.error_messages}',
        children: formChildren,
      }],
    },
  };
}

const NOTICE = {
  id: 'NOTICE',
  title: TITLE,
  data: declare(noticeData('sealed')),
  layout: {
    type: 'SingleColumnLayout',
    children: [
      CAPTION,
      { type: 'TextHeading', text: '${data.notice_title}' },
      { type: 'TextBody', text: '${data.notice_body}' },
      { type: 'Footer', label: '${data.close_label}', 'on-click-action': { name: 'data_exchange', payload: { screen: 'NOTICE' } } },
    ],
  },
};

// The complete payload keeps FDE's shape ({ obs612: outcome, form_id }), so the same completion handler reads both.
const DONE = {
  id: 'DONE',
  title: TITLE,
  terminal: true,
  success: true,
  data: declare(doneData('submitted', '00000000-0000-4000-8000-000000000000')),
  layout: {
    type: 'SingleColumnLayout',
    children: [
      CAPTION,
      { type: 'TextHeading', text: '${data.done_title}' },
      { type: 'TextBody', text: '${data.done_body}' },
      { type: 'Footer', label: '${data.done_label}', 'on-click-action': { name: 'complete', payload: { obs612: '${data.outcome}', form_id: '${data.form_id}' } } },
    ],
  },
};

function buildFlow() {
  const screens = [...SCREENS.map(screenJson), NOTICE, DONE];
  const routing = {};
  for (const s of SCREENS) routing[s.id] = [...[nextOf(s.id)].filter(Boolean), 'DONE'];
  routing.NOTICE = ['DONE'];
  routing.DONE = [];
  return { version: FLOW_VERSION, data_api_version: DATA_API_VERSION, routing_model: routing, screens };
}

module.exports = {
  FLOW_VERSION,
  DATA_API_VERSION,
  TITLE,
  STR,
  SCREENS,
  FIRST_SCREEN,
  pathFor,
  nextOf,
  isSubmitScreen,
  screenById,
  fieldsOf,
  indicatorScreenId,
  levelOptions,
  focusOptions,
  mergeDraft,
  checkScreen,
  whatIsMissing,
  missingNote,
  screenData,
  noticeData,
  doneData,
  buildFlow,
  portalFields,
  errorsByKey,
  portalSections,
};
